        internal async Task RunTask(string title,string[] steps,Func<IProgress<string>,Task<string>> operation,Action<string> apply){
            if(busy)return;busy=true;lastFailed=false;sounds.Stop();FinishTransition();art[Step].Preview(WizardArt.Duration);titles[Step].Preview();SetBusy(true);
            try{using(var form=new WizardTaskForm(title,steps,operation,Motion.Checked)){form.ShowDialog(this);if(form.Error!=null){lastFailed=true;LastFailure=form.Error.ToString();SetStatus(form.Error.Message,true);return;}apply(form.Result);SetStatus("本步操作已完成，可查看上方结果。验证以实际回执为准。");}}
            finally{busy=false;SetBusy(false);}
        }
