            layoutPanel.Controls.Add(new Label{Text=note,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft,ForeColor=Color.FromArgb(157,160,177),Margin=new Padding(2,0,10,6)},textCol,1);
            layoutPanel.Controls.Add(a,artCol,2);
            var fallbackViewport=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Color.Transparent,Name="onboardingScroll_"+step};layoutPanel.Controls.Add(fallbackViewport,textCol,2);var fallbackFlow=new BufferedFlow{Dock=DockStyle.Top,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,BackColor=Color.Transparent,Padding=new Padding(2,8,22,12)};choices.Add(fallbackFlow);fallbackViewport.Controls.Add(fallbackFlow);fallbackViewport.SizeChanged+=(s,e)=>{foreach(Control c in fallbackFlow.Controls){int width=Math.Max(220,fallbackViewport.ClientSize.Width-30);if(c is Label){((Label)c).MaximumSize=new Size(width,0);c.MinimumSize=new Size(width,0);}c.Width=width;}};
        }
        Label AddCopy(int step,string value,bool prominent){var label=new Label{Text=value,AutoSize=true,MaximumSize=new Size(880,0),Width=800,Margin=new Padding(0,5,0,12),ForeColor=prominent?ForeColor:Color.FromArgb(157,160,177),Font=new Font(Font.FontFamily,prominent?10:9)};choices[step].Controls.Add(label);return label;}
        void Actions(int step,params AnimeButton[] buttons){var row=new BufferedFlow{AutoSize=true,WrapContents=true,BackColor=BackColor,Margin=new Padding(0,3,0,5)};foreach(var b in buttons)row.Controls.Add(b);choices[step].Controls.Add(row);}
        AnimeButton Button(string text,Action action,bool primary){var b=new AnimeButton{Text=text,Font=Font,Width=198,Height=44,MinimumSize=new Size(120,44),Margin=new Padding(0,0,10,10),Padding=new Padding(10,0,10,0),Cursor=Cursors.Hand,BackColor=primary?Color.FromArgb(243,245,248):Color.FromArgb(27,28,33),ForeColor=primary?Color.FromArgb(11,13,18):ForeColor,BorderSize=0,AccessibleName=text};b.Click+=(s,e)=>{try{action();}catch(Exception error){LastFailure=error.ToString();SetStatus(error.Message,true);}};return b;}
        AnimeButton Button(string text,Func<Task> action,bool primary){var b=Button(text,()=>{},primary);b.Click+=async(s,e)=>{try{PendingAction=action();await PendingAction;}catch(Exception error){LastFailure=error.ToString();SetStatus(error.Message,true);}};return b;}
        void SyncEngine(){var c=Flow.Config;Engine.SelectedIndex=c.voice.engine=="cosyvoice"?0:c.voice.gptVariant=="v5turbo"?1:2;}
        string VoiceDescription(){var c=Flow.Config;return "当前声音："+(c.voice.engine=="cosyvoice"?"CosyVoice":"GPT-SoVITS · "+c.voice.gptVariant)+"\r\n"+Flow.Resources();}
        void OpenDoc(string name){ServiceClient.Open(Flow.Store.Resolve(name));}
        void OpenDirectory(string relative){string path=Flow.Store.Resolve(relative);Directory.CreateDirectory(path);ServiceClient.Open(path);}
        async void OnClosing(object sender,FormClosingEventArgs e){if(busy){e.Cancel=true;SetStatus("当前操作仍在执行。试听可点“停止试听”；其他操作结束后可退出。",true);return;}if(DialogResult!=DialogResult.OK&&!closingAfterCleanup&&Flow.Service.Owned!=null){e.Cancel=true;closingAfterCleanup=true;try{if(await Flow.Service.Running())await Flow.Service.Stop();}catch(Exception error){LastFailure=error.ToString();SetStatus(error.Message,true);}Close();}}
        protected override void Dispose(bool disposing){if(disposing){FinishTransition();sounds.Dispose();tips.Dispose();}base.Dispose(disposing);}
    }
}
